[CmdletBinding()]param([Parameter(Mandatory=$true)][string]$TaskDirectory,[Parameter(Mandatory=$true)][string]$InvariantsJson)
$ErrorActionPreference='Stop';Import-Module (Join-Path $PSScriptRoot 'PipelineProtocolV2.psm1') -Force;$v=Get-Content -Raw $InvariantsJson|ConvertFrom-Json;$items=@($v.invariants);if($items.Count -eq 0){throw 'invariants must not be empty'};$ids=@{};foreach($i in $items){if($i.id -notmatch '^NEG-' -or $ids.ContainsKey($i.id)){throw 'invariant ids must be unique NEG-*'};$ids[$i.id]=$true;if($i.type -notin @('forbidden_path','forbidden_symbol','must_remain_deleted')){throw "invalid invariant type: $($i.id)"};if([string]::IsNullOrWhiteSpace([string]$i.selector)){throw "selector required: $($i.id)"};if(@($i.requirement_ids).Count -eq 0 -or @($i.check_ids).Count -eq 0){throw "refs required: $($i.id)"}};$dir=Join-Path $TaskDirectory 'negative-invariant-revisions';[IO.Directory]::CreateDirectory($dir)|Out-Null;$n=1;while($true){$id='NEGSET-{0:D4}' -f $n;$file=Join-Path $dir "$id.json";try{$doc=[ordered]@{protocol_version=2;revision_id=$id;invariants=$items;created_at=[datetime]::UtcNow.ToString('o')};Write-PipelineImmutableJson $file $doc|Out-Null;break}catch{$n++}};$hash=(Get-FileHash $file -Algorithm SHA256).Hash.ToLowerInvariant();Write-AtomicJson (Join-Path $TaskDirectory 'negative-invariants-current.json') ([ordered]@{protocol_version=2;type='negative_invariants';revision_id=$id;path=(Join-Path 'negative-invariant-revisions' "$id.json");sha256=$hash});$doc|ConvertTo-Json -Depth 20
